EXTRA_FAQ = {'en': [['Who receives my photo?', 'Only after you agree before each analysis, your photo, optional age and language are sent through our server to Anthropic’s Claude API. You can cancel instead. The analysis is cosmetic guidance, not a medical diagnosis. Read the privacy policy for provider retention details.'], ['I paid but cannot scan. What should I do?', 'Use Restore Purchases on the subscription screen with the same Apple Account used for your purchase. Check that the subscription is active with Apple. If access is still missing, contact contact@glasify.app; Apple handles billing and refunds, while we can help with app access.'], ['Does deleting my account cancel my subscription?', 'No. Delete Account in the app removes your Glasify account and scans. Cancel the Apple subscription separately to stop renewal.']], 'no': [['Hvem mottar bildet mitt?', 'Først når du samtykker før hver analyse, sendes bildet, eventuell alder og språket ditt via serveren vår til Anthropics Claude API. Du kan avbryte i stedet. Analysen er kosmetisk veiledning, ikke en medisinsk diagnose. Se personvernerklæringen for leverandørens lagringsregler.'], ['Jeg har betalt, men kan ikke skanne. Hva gjør jeg?', 'Bruk Gjenopprett kjøp på abonnementsskjermen med samme Apple-konto som ved kjøpet. Sjekk at abonnementet er aktivt hos Apple. Mangler du fortsatt tilgang, kontakt contact@glasify.app; Apple håndterer betaling og refusjon, mens vi kan hjelpe med tilgang i appen.'], ['Sier kontosletting opp abonnementet?', 'Nei. Slett konto i appen fjerner Glasify-kontoen og skanningene dine. Si opp Apple-abonnementet separat for å stoppe fornyelsen.']], 'se': [['Vem tar emot mitt foto?', 'Först när du samtycker före varje analys skickas fotot, eventuell ålder och ditt språk via vår server till Anthropics Claude API. Du kan avbryta i stället. Analysen är kosmetisk vägledning, inte en medicinsk diagnos. Läs integritetspolicyn för leverantörens lagringsregler.'], ['Jag har betalat men kan inte skanna. Vad gör jag?', 'Använd Återställ köp på abonnemangsskärmen med samma Apple-konto som vid köpet. Kontrollera att abonnemanget är aktivt hos Apple. Saknar du fortfarande åtkomst, kontakta contact@glasify.app; Apple hanterar betalning och återbetalning, medan vi kan hjälpa med åtkomst i appen.'], ['Avslutas abonnemanget när jag raderar kontot?', 'Nej. Radera konto i appen tar bort ditt Glasify-konto och dina skanningar. Avsluta Apple-abonnemanget separat för att stoppa förnyelsen.']], 'dk': [['Hvem modtager mit foto?', 'Først når du samtykker før hver analyse, sendes fotoet, eventuel alder og dit sprog via vores server til Anthropics Claude API. Du kan annullere i stedet. Analysen er kosmetisk vejledning, ikke en medicinsk diagnose. Læs privatlivspolitikken for leverandørens opbevaringsregler.'], ['Jeg har betalt, men kan ikke scanne. Hvad gør jeg?', 'Brug Gendan køb på abonnementsskærmen med samme Apple-konto som ved købet. Tjek, at abonnementet er aktivt hos Apple. Mangler du stadig adgang, kontakt contact@glasify.app; Apple håndterer betaling og refusion, mens vi kan hjælpe med adgang i appen.'], ['Opsiger kontosletning abonnementet?', 'Nej. Slet konto i appen fjerner din Glasify-konto og dine scanninger. Opsig Apple-abonnementet separat for at stoppe fornyelsen.']]}
for route, questions in EXTRA_FAQ.items():
    COPY[route][19].extend(questions)

LANG = {'no':'nb','se':'sv','dk':'da','en':'en'}
def page(route, root=False):
    t=COPY[route]
    links=''.join(f'<a href="/{r}/" lang="{LANG[r]}" hreflang="{LANG[r]}"'+(' aria-current="page"' if r==route and not root else '')+f'>{name}</a>' for r,name in [('no','Norsk'),('se','Svenska'),('dk','Dansk'),('en','English')])
    alternates=''.join(f'<link rel="alternate" hreflang="{LANG[r]}" href="https://glasify.app/{r}/">' for r in COPY)
    messages=e(json.dumps(dict(zip(['pending','success','error','network'],t[8:12])),ensure_ascii=False),quote=True)
    faq=''.join(f'<details><summary>{e(q)}</summary><p>{a}</p></details>' for q,a in t[19])
    return f'''<!doctype html>
<html lang="{LANG[route]}" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#1a1214"><title>Glasify — {t[0]}</title><meta name="description" content="{e(t[2],quote=True)}"><link rel="canonical" href="https://glasify.app/{route}/">{alternates}<link rel="alternate" hreflang="x-default" href="https://glasify.app/"><link rel="stylesheet" href="/assets/style.css">{('<script src="/assets/redirect.js" defer></script>' if root else '')}<script src="/assets/waitlist.js" defer></script></head>
<body><div class="wrap"><nav class="top" aria-label="Glasify"><div class="logo">Glas<span>ify</span></div><div class="languages">{links}</div></nav></div>
<main>{('<p class="wrap privacy-note">We use GeoJS to select a language from your IP country. GeoJS receives your IP address; only a country code is requested. No cookies or precise location are used. If the lookup fails, we use English. You can always choose a language above.</p>' if root else '')}<div class="wrap hero"><span class="eyebrow">✨ {t[0]}</span><h1>{t[1]}</h1><p class="sub">{t[2]}</p><div class="soon">{t[3]}</div><div class="waitlist"><p>{t[4]}</p>
<form id="waitlistForm" data-messages="{messages}"><fieldset class="platforms"><legend>{t[5]}</legend><label><input type="radio" name="platform" value="ios" checked> iPhone</label><label><input type="radio" name="platform" value="android"> Android</label></fieldset><input type="email" id="waitlistEmail" name="email" autocomplete="email" placeholder="{t[6]}" aria-label="{t[6]}" required><button type="submit" disabled>{t[7]}</button></form><p id="waitlistMessage" role="status" aria-live="polite"></p><noscript><p>{t[18]}</p></noscript><p class="privacy-note">{t[17]} <a href="https://privacy.glasify.app/{'' if route == 'en' else 'privacy-' + LANG[route] + '.html'}">{t[13]}</a>.</p></div></div></main>
<section class="wrap faq" aria-labelledby="faq"><h2 id="faq">{t[12]}</h2>{faq}</section><footer><div class="wrap"><div class="links"><a href="https://privacy.glasify.app/{'' if route == 'en' else 'privacy-' + LANG[route] + '.html'}">{t[13]}</a><a href="mailto:contact@glasify.app">{t[14]}</a></div><p>{t[15]}</p><p>© 2026 Planting Software. {t[16]}</p></div></footer></body></html>'''
for route in COPY:
    (ROOT/route).mkdir(exist_ok=True)
    (ROOT/route/'index.html').write_text(page(route))
(ROOT/'index.html').write_text(page('en',root=True))
